procedure:public.borrar_mes_permanente(t.source_code:
DECLARE
  v_order_ids      UUID[];
  v_orders_count   INTEGER;
  v_items_count    INTEGER;
  v_payments_count INTEGER;
  v_movs_count     INTEGER;
BEGIN
  -- Verificar permisos
  IF NOT EXISTS (
    SELECT 1 FROM public.employees WHERE id = auth.uid() AND rol = 'admin'
  ) THEN
    RAISE EXCEPTION 'Solo admin puede borrar meses permanentemente';
  END IF;

  -- Verificar que hay registros archivados en ese período
  IF NOT EXISTS (
    SELECT 1 FROM public.orders
    WHERE creado_en >= p_start AND creado_en <= p_end AND archivado = true
    LIMIT 1
  ) AND NOT EXISTS (
    SELECT 1 FROM public.payments
    WHERE creado_en >= p_start AND creado_en <= p_end AND archivado = true
    LIMIT 1
  ) AND NOT EXISTS (
    SELECT 1 FROM public.movements
    WHERE fecha >= p_start AND fecha <= p_end AND archivado = true
    LIMIT 1
  ) THEN
    RAISE EXCEPTION 'No hay registros archivados en ese período. Archiva el mes primero antes de borrarlo.';
  END IF;

  -- Recopilar IDs de órdenes archivadas del período
  SELECT ARRAY_AGG(id) INTO v_order_ids
  FROM public.orders
  WHERE creado_en >= p_start
    AND creado_en <= p_end
    AND archivado = true;

  -- Borrar order_items de esas órdenes
  IF v_order_ids IS NOT NULL THEN
    DELETE FROM public.order_items
    WHERE order_id = ANY(v_order_ids);
    GET DIAGNOSTICS v_items_count = ROW_COUNT;

    -- Borrar orders archivadas
    DELETE FROM public.orders
    WHERE id = ANY(v_order_ids);
    GET DIAGNOSTICS v_orders_count = ROW_COUNT;
  ELSE
    v_items_count  := 0;
    v_orders_count := 0;
  END IF;

  -- Borrar payments archivados del período
  DELETE FROM public.payments
  WHERE creado_en >= p_start
    AND creado_en <= p_end
    AND archivado = true;
  GET DIAGNOSTICS v_payments_count = ROW_COUNT;

  -- Borrar movimientos archivados del período
  DELETE FROM public.movements
  WHERE fecha >= p_start
    AND fecha <= p_end
    AND archivado = true;
  GET DIAGNOSTICS v_movs_count = ROW_COUNT;

  RETURN jsonb_build_object(
    'orders',      v_orders_count,
    'order_items', v_items_count,
    'payments',    v_payments_count,
    'movements',   v_movs_count
  );
END;

procedure:public.borrar_mes_permanente(t.definition:
CREATE OR REPLACE FUNCTION public.borrar_mes_permanente(p_start timestamp with time zone, p_end timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_order_ids      UUID[];
  v_orders_count   INTEGER;
  v_items_count    INTEGER;
  v_payments_count INTEGER;
  v_movs_count     INTEGER;
BEGIN
  -- Verificar permisos
  IF NOT EXISTS (
    SELECT 1 FROM public.employees WHERE id = auth.uid() AND rol = 'admin'
  ) THEN
    RAISE EXCEPTION 'Solo admin puede borrar meses permanentemente';
  END IF;

  -- Verificar que hay registros archivados en ese período
  IF NOT EXISTS (
    SELECT 1 FROM public.orders
    WHERE creado_en >= p_start AND creado_en <= p_end AND archivado = true
    LIMIT 1
  ) AND NOT EXISTS (
    SELECT 1 FROM public.payments
    WHERE creado_en >= p_start AND creado_en <= p_end AND archivado = true
    LIMIT 1
  ) AND NOT EXISTS (
    SELECT 1 FROM public.movements
    WHERE fecha >= p_start AND fecha <= p_end AND archivado = true
    LIMIT 1
  ) THEN
    RAISE EXCEPTION 'No hay registros archivados en ese período. Archiva el mes primero antes de borrarlo.';
  END IF;

  -- Recopilar IDs de órdenes archivadas del período
  SELECT ARRAY_AGG(id) INTO v_order_ids
  FROM public.orders
  WHERE creado_en >= p_start
    AND creado_en <= p_end
    AND archivado = true;

  -- Borrar order_items de esas órdenes
  IF v_order_ids IS NOT NULL THEN
    DELETE FROM public.order_items
    WHERE order_id = ANY(v_order_ids);
    GET DIAGNOSTICS v_items_count = ROW_COUNT;

    -- Borrar orders archivadas
    DELETE FROM public.orders
    WHERE id = ANY(v_order_ids);
    GET DIAGNOSTICS v_orders_count = ROW_COUNT;
  ELSE
    v_items_count  := 0;
    v_orders_count := 0;
  END IF;

  -- Borrar payments archivados del período
  DELETE FROM public.payments
  WHERE creado_en >= p_start
    AND creado_en <= p_end
    AND archivado = true;
  GET DIAGNOSTICS v_payments_count = ROW_COUNT;

  -- Borrar movimientos archivados del período
  DELETE FROM public.movements
  WHERE fecha >= p_start
    AND fecha <= p_end
    AND archivado = true;
  GET DIAGNOSTICS v_movs_count = ROW_COUNT;

  RETURN jsonb_build_object(
    'orders',      v_orders_count,
    'order_items', v_items_count,
    'payments',    v_payments_count,
    'movements',   v_movs_count
  );
END;
$function$

procedure:public.desanular_pago(uuid,uui.source_code:
DECLARE
  v_order_id UUID;
  v_item_ids UUID[];
  v_anulado BOOLEAN;
  v_creado_en TIMESTAMP WITH TIME ZONE;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.employees WHERE id = p_employee_id AND rol = 'admin') THEN
    RAISE EXCEPTION 'Solo admin puede desanular pagos';
  END IF;

  SELECT order_id, item_ids, anulado, creado_en INTO v_order_id, v_item_ids, v_anulado, v_creado_en
  FROM public.payments WHERE id = p_payment_id FOR UPDATE;

  IF v_order_id IS NULL THEN
    RAISE EXCEPTION 'Pago no encontrado';
  END IF;

  IF NOT v_anulado THEN
    RAISE EXCEPTION 'Este pago no está anulado';
  END IF;

  IF v_creado_en::date <> NOW()::date THEN
    RAISE EXCEPTION 'Solo se puede desanular un pago el mismo día en que se anuló';
  END IF;

  -- Revertir la anulación
  UPDATE public.payments SET anulado = false, motivo_anulacion = NULL WHERE id = p_payment_id;

  -- Volver a marcar esos items como pagados
  UPDATE public.order_items SET pagado = true WHERE id = ANY(v_item_ids);

  -- Si con esto ya no quedan items sin pagar, volver a cerrar el pedido
  IF NOT EXISTS (
    SELECT 1 FROM public.order_items WHERE order_id = v_order_id AND pagado = false AND cancelado = false
  ) THEN
    UPDATE public.orders SET estado = 'cerrado' WHERE id = v_order_id;
  END IF;
END;

